from pathlib import Path
from PIL import Image
import numpy as np,cv2,json
s=Path(__file__).resolve().parent;original=np.array(Image.open(s/'Crops/paper.png').convert('RGB'));h,w=original.shape[:2];im=Image.open(s/'ScenarioPaperRepair/booster_medallion_trial01.png').convert('RGB');im.load();repair=np.array(im.resize((w,h),Image.Resampling.LANCZOS));mask=np.zeros((h,w),'uint8');mask[22:h-15,21:w-15]=255
# Feather only inside this bounded mask; all source outer-frame pixels are untouched.
distance=cv2.distanceTransform((mask>0).astype('uint8'),cv2.DIST_L2,5);blend=np.minimum(distance/7,1)[...,None];rgb=np.round(original*(1-blend)+repair*blend).astype('uint8');assert np.array_equal(rgb[mask==0],original[mask==0]);Image.fromarray(rgb).save(s/'Inputs/paper_native.png');Image.fromarray(mask).save(s/'RepairMasks/paper.png');Image.fromarray(np.round(blend[:,:,0]*255).astype('uint8')).save(s/'RepairMasks/paper_blend.png')
p=s/'Assessment.json';d=json.loads(p.read_text());d['paperRepair']='Local letter removal left ghosts and broad texture damage. One Scenario generation reconstructs only covered paper; original frame retained outside explicit mask. 13CU.';p.write_text(json.dumps(d,indent=2))
p=s/'README.md';t=p.read_text().replace('No new RGB generation.','One bounded paper-surface generation follows the failed local cleanup; other source illustrations are not regenerated.').replace('Remaining limitations:', 'Local parchment clearing was rejected after visible ghost letters and a stronger threshold damaged texture. ScenarioPaperRepair.py submitted one13CU repair. ApplyPaperRepair.py composites only its interior through a bounded seven-pixel feather mask, retaining original outer-frame RGB. Run this after RefineNativeInputs.py and before PrepareFinal.py.\n\nRemaining limitations:');p.write_text(t)
p=s.parent/'QA/ScenarioAudit.json';d=json.loads(p.read_text());cost=json.loads((s/'ScenarioPaperRepair/Billing.json').read_text())['cuCost'];d['boundedPaperRepair']={'cuCost':cost,'status':'success','scope':'Only hidden/lettered paper face composited through explicit blend mask','evidence':'Sources/ScenarioPaperRepair'};d['totalJobs']=26;d['totalCU']=sum(r['cuCost'] for r in d['jobs'])+cost;d['rgbGenerations']=1;p.write_text(json.dumps(d,indent=2));print('Bounded paper repair applied; total',d['totalCU'],'CU')
